private IState move()
    {
        if (!checkForTarget())
        {
            return CombatAIStates.NO_TARGET;
        }

        final ThreatTableEntry nextTarget = user.getThreatTable().getTarget();
        if (nextTarget == null)
        {
            return CombatAIStates.NO_TARGET;
        }

        final boolean canSeeTarget = user.getSensing().hasLineOfSight(target);
        if (canSeeTarget)
        {
            nextTarget.setLastSeen(user.level.getGameTime());
        }
        else if ((user.level.getGameTime() - nextTarget.getLastSeen()) > STOP_PERSECUTION_AFTER)
        {
            resetTarget();
            return null;
        }

        if (!isInAttackDistance(target) || !canSeeTarget)
        {
            user.lookAt(target, (float) HALF_ROTATION, (float) HALF_ROTATION);
            user.getLookControl().setLookAt(target, (float) HALF_ROTATION, (float) HALF_ROTATION);

            if (pathAttempts > 5 || (targetPath != null && targetPath.isDone() && targetPath.failedToReachDestination()))
            {
                pathAttempts = 0;
                targetPath = null;

                user.getThreatTable().addThreat(target, -1);
                if (nextTarget.getThreat() < 5)
                {
                    resetTarget();
                    return null;
                }
            }

            if (targetPath == null ||
                  user.getNavigation().isDone() ||
                  (targetPath.isDone() && targetPath.hasPath() && targetPath.getPath().getTarget().distSqr(target.blockPosition()) > Math.pow(getAttackDistance(), 2) - 1))
            {
                targetPath = moveInAttackPosition(target);
                pathAttempts++;
            }
        }

        return null;
    }

@Override
    public void resetTarget()
    {
        super.resetTarget();
        targetPath = null;
        pathAttempts = 0;
    }

protected IState tryAttack()
    {
        if (!checkForTarget() || !canAttack())
        {
            return CombatAIStates.NO_TARGET;
        }

        if (nextAttackTime >= user.level.getGameTime() || !isInDistanceForAttack(target))
        {
            return null;
        }

        if (user.getSensing().hasLineOfSight(target))
        {
            pathAttempts = 0;
            user.getLookControl().setLookAt(target);
            doAttack(target);
            nextAttackTime = user.level.getGameTime() + getAttackDelay();
        }

        return null;
    }

protected boolean checkForTarget()
    {
        if (target != null && !target.isAlive())
        {
            onTargetDied(target);
            target = null;
        }

        final ThreatTableEntry nextTarget = user.getThreatTable().getTarget();
        if (nextTarget == null)
        {
            return false;
        }

        if (isEntityValidTarget(nextTarget.getEntity()))
        {
            if (target != nextTarget.getEntity())
            {
                target = nextTarget.getEntity();
                onTargetChange(target);
            }

            return true;
        }
        else
        {
            resetTarget();
            return false;
        }
    }

public boolean isEntityValidTarget(final LivingEntity target)
    {
        if (target == user || target == null || !target.isAlive() || !isWithinPersecutionDistance(target) || target instanceof FakePlayer)
        {
            return false;
        }

        if (target == user.getLastHurtByMob())
        {
            return true;
        }

        return isAttackableTarget(target);
    }

public void resetTarget()
    {
        if (target == null)
        {
            return;
        }

        if (user.getLastHurtMob() == target)
        {
            user.setLastHurtMob(null);
        }

        if (user.getLastHurtByMob() == target)
        {
            user.setLastHurtByMob(null);
        }

        user.getThreatTable().markInvalidTarget();
        target = null;
    }

protected boolean searchNearbyTarget()
    {
        if (checkForTarget())
        {
            return true;
        }

        final List<LivingEntity> entities = user.level.getEntitiesOfClass(LivingEntity.class, getSearchArea());

        if (entities.isEmpty())
        {
            return false;
        }

        boolean foundTarget = false;
        for (final LivingEntity entity : entities)
        {
            if (!entity.isAlive())
            {
                continue;
            }

            if (skipSearch(entity))
            {
                return false;
            }

            if (isEntityValidTarget(entity) && user.getSensing().hasLineOfSight(entity))
            {
                user.getThreatTable().addThreat(entity, 0);
                foundTarget = true;
            }
        }

        return foundTarget;
    }

protected boolean isAttackableTarget(final LivingEntity target)
    {
        return target instanceof Enemy && !user.getClass().isInstance(target);
    }

@Override
    protected void doAttack(final LivingEntity target)
    {
        if (user.distanceToSqr(target) < RANGED_FLEE_SQDIST)
        {
            if (user.getRandom().nextInt(FLEE_CHANCE) == 0 &&
                  !((AbstractBuildingGuards) user.getCitizenData().getWorkBuilding()).getTask().equals(GuardTaskSetting.GUARD))
            {
                EntityNavigationUtils.walkAwayFrom(user, target.blockPosition(), (int) (getAttackDistance() / 2.0), getCombatMovementSpeed());
            }
        }
        else
        {
            user.getNavigation().stop();
        }

        user.swing(InteractionHand.MAIN_HAND);

        final int level = user.getCitizenData().getCitizenSkillHandler().getLevel(ModGuardTypes.druid.get().getSecondarySkill());
        final int time = user.getCitizenData().getCitizenSkillHandler().getLevel(ModGuardTypes.druid.get().getPrimarySkill()) * 20;

        final float inaccuracy = 99f / level;
        final MobEffect effect;
        final ItemStack stack = new ItemStack(Items.SPLASH_POTION);
        boolean gotMaterial = false;
        BiPredicate<LivingEntity, MobEffect> predicate;
        if (user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(DRUID_USE_POTIONS) > 0
              && InventoryUtils.hasItemInItemHandler(user.getInventoryCitizen(), item -> item.getItem() == ModItems.magicpotion))
        {
            gotMaterial = true;
        }
        if (AbstractEntityAIGuard.isAttackableTarget(user, target))
        {
            effect = ADVERSE_EFFECTS.get(user.getRandom().nextInt(gotMaterial ? 2 : 1));
            predicate = (entity, eff) -> AbstractEntityAIGuard.isAttackableTarget(user, entity);
        }
        else
        {
            effect = SUPPORT_EFFECTS.get(user.getRandom().nextInt(gotMaterial ? 4 : 1));
            predicate = (entity, eff) -> !AbstractEntityAIGuard.isAttackableTarget(user, entity);
        }

        PotionUtils.setCustomEffects(stack, Collections.singleton(new MobEffectInstance(effect, time, gotMaterial ? 2 : 0)));
        DruidPotionEntity.throwPotionAt(stack, target, user, user.getCommandSenderWorld(), POTION_VELOCITY, inaccuracy, predicate);

        if (gotMaterial)
        {
            InventoryUtils.removeStackFromItemHandler(user.getCitizenData().getInventory(), new ItemStack(ModItems.magicpotion, 1), 1);
        }

        this.instantEffect = effect.isInstantenous();

        user.setItemInHand(InteractionHand.MAIN_HAND, stack);

        user.getThreatTable().removeCurrentTarget();

        user.getCitizenExperienceHandler().addExperience(PER_POTION_XP);
    }

@Override
    protected boolean isAttackableTarget(final LivingEntity entity)
    {
        return (AbstractEntityAIGuard.isAttackableTarget(user, entity)
                  || (entity instanceof IThreatTableEntity && ((IThreatTableEntity) entity).getThreatTable().getTarget() != null)
                  || (entity instanceof Player && entity.getLastHurtByMobTimestamp() != 0 && entity.tickCount > entity.getLastHurtByMobTimestamp()
                        && entity.tickCount - entity.getLastHurtByMobTimestamp() < 20 * 30))
                 && !wasAffectedByDruid(entity);
    }

@Override
    protected boolean searchNearbyTarget()
    {
        if (checkForTarget())
        {
            return true;
        }

        final List<LivingEntity> entities = user.level.getEntitiesOfClass(LivingEntity.class, getSearchArea());

        if (entities.isEmpty())
        {
            return false;
        }

        int targetsUnderEffect = 0;
        boolean foundTarget = false;
        for (final LivingEntity entity : entities)
        {
            if (!entity.isAlive())
            {
                continue;
            }

            if (skipSearch(entity))
            {
                return false;
            }

            if (isEntityValidTarget(entity))
            {
                if (user.hasLineOfSight(entity))
                {
                    user.getThreatTable().addThreat(entity, 0);
                    foundTarget = true;
                }
            }
            else if (wasAffectedByDruid(entity))
            {
                targetsUnderEffect++;
            }
        }

        return foundTarget && targetsUnderEffect <= parentAI.building.getBuildingLevelEquivalent() * 2;
    }

@Override
    public boolean canAttack()
    {
        final int weaponSlot =
          InventoryUtils.getFirstSlotOfItemHandlerContainingEquipment(user.getInventoryCitizen(), getWeaponType(), 0, user.getCitizenData().getWorkBuilding().getMaxEquipmentLevel());

        if (weaponSlot != -1)
        {
            CitizenItemUtils.setHeldItem(user, InteractionHand.MAIN_HAND, weaponSlot);
            if (nextAttackTime - BOW_HOLDING_DELAY >= user.level.getGameTime() && !user.isUsingItem())
            {
                user.startUsingItem(InteractionHand.MAIN_HAND);
            }
            return true;
        }

        return false;
    }

@Override
    protected boolean checkForTarget()
    {
        final boolean validTarget = super.checkForTarget();

        if (!validTarget && user.isUsingItem())
        {
            user.stopUsingItem();
        }

        return validTarget;
    }

@Override
    protected void doAttack(final LivingEntity target)
    {
        if (user.distanceToSqr(target) < RANGED_FLEE_SQDIST)
        {
            if (user.getRandom().nextInt(FLEE_CHANCE) == 0 &&
                  !((AbstractBuildingGuards) user.getCitizenData().getWorkBuilding()).getTask().equals(GuardTaskSetting.GUARD))
            {
                EntityNavigationUtils.walkAwayFrom(user, target.blockPosition(), (int) (getAttackDistance() / 2.0), getCombatMovementSpeed());
            }
        }
        else
        {
            user.getNavigation().stop();
        }

        user.getCitizenData().setVisibleStatus(ARCHER_COMBAT);
        user.swing(InteractionHand.MAIN_HAND);
        user.stopUsingItem();

        int amountOfArrows = 1;
        if (user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(DOUBLE_ARROWS) > 0)
        {
            if (user.getRandom().nextDouble() < user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(DOUBLE_ARROWS))
            {
                amountOfArrows++;
            }
        }

        for (int i = 0; i < amountOfArrows; i++)
        {
            final AbstractArrow arrow = CombatUtils.createArrowForShooter(user);

            if (user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(ARROW_PIERCE) > 0)
            {
                arrow.setPierceLevel((byte) 2);
            }

            // Add bow enchant effects: Knocback and fire
            final ItemStack bow = user.getItemInHand(InteractionHand.MAIN_HAND);

            if (EnchantmentHelper.getItemEnchantmentLevel(Enchantments.FLAMING_ARROWS, bow) > 0)
            {
                arrow.setSecondsOnFire(5);
            }
            final int k = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.PUNCH_ARROWS, bow);
            if (k > 0)
            {
                arrow.setKnockback(k);
            }

            double damage = calculateDamage(arrow);
            if (isMarksman())
            {
                arrow.setShotFromCrossbow(true);
            }
            arrow.setBaseDamage(damage);

            final float chance = HIT_CHANCE_DIVIDER / (user.getCitizenData().getCitizenSkillHandler().getLevel(Skill.Adaptability) + 1);
            CombatUtils.shootArrow(arrow, target, chance);
            user.playSound(SoundEvents.SKELETON_SHOOT, (float) BASIC_VOLUME, (float) SoundUtils.getRandomPitch(user.getRandom()));
        }

        target.setLastHurtByMob(user);
        CitizenItemUtils.damageItemInHand(user, InteractionHand.MAIN_HAND, 1);
        user.stopUsingItem();
    }

@Override
    protected void doAttack(final LivingEntity target)
    {
        if (user.distanceTo(target) > 1)
        {
            moveInAttackPosition(target);
        }

        user.swing(InteractionHand.MAIN_HAND);
        user.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, (float) BASIC_VOLUME, (float) SoundUtils.getRandomPitch(user.getRandom()));

        final double damageToBeDealt = getAttackDamage();
        DamageSource source = target.level.damageSources().source(DamageSourceKeys.GUARD, user);
        if (MineColonies.getConfig().getServer().pvp_mode.get() && target instanceof Player)
        {
            source = target.level.damageSources().source(DamageSourceKeys.GUARD_PVP, user);
        }

        final int fireLevel = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.FIRE_ASPECT, user.getItemInHand(InteractionHand.MAIN_HAND));
        if (fireLevel > 0)
        {
            target.setSecondsOnFire(fireLevel * 4);
        }

        if (user.level.getGameTime() - lastAoeUseTime > KNOCKBACK_COOLDOWN)
        {
            doAoeAttack(source, damageToBeDealt);
        }

        if (isHuscarl())
        {
            double share = (50 + user.getCitizenData().getCitizenSkillHandler().getLevel(Skill.Adaptability) / 2.0) / 100.0;
            target.hurt(target.level.damageSources().source(DamageSourceKeys.PIERCE, user), (float) damageToBeDealt * (float) share);
            target.hurt(source, (float) damageToBeDealt * (float) (1.0 - share));
        }
        else
        {
            target.hurt(source, (float) damageToBeDealt);
        }

        target.setLastHurtByMob(user);

        if (target instanceof Mob && user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(KNIGHT_TAUNT) > 0)
        {
            ((Mob) target).setTarget(user);
            if (target instanceof IThreatTableEntity)
            {
                ((IThreatTableEntity) target).getThreatTable().addThreat(user, 5);
            }
        }

        user.stopUsingItem();
        user.getCitizenData().setVisibleStatus(getCombatStatus());
        CitizenItemUtils.damageItemInHand(user, InteractionHand.MAIN_HAND, 1);
    }

private void doAoeAttack(final DamageSource source, final double damageToBeDealt)
    {
        if (user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(KNIGHT_WHIRLWIND) > 0
              && user.getRandom().nextInt(KNOCKBACK_CHANCE) == 0)
        {
            List<LivingEntity> entities = user.level.getEntitiesOfClass(LivingEntity.class, user.getBoundingBox().inflate(2.0D, 0.5D, 2.0D));
            for (LivingEntity livingentity : entities)
            {
                if (livingentity != user && isEntityValidTarget(livingentity) && (!(livingentity instanceof ArmorStand)))
                {
                    livingentity.knockback(
                      2F,
                      Mth.sin(livingentity.getYRot() * ((float) Math.PI)),
                      (-Mth.cos(livingentity.getYRot() * ((float) Math.PI))));
                    livingentity.hurt(source, (float) (damageToBeDealt / entities.size()));
                }
            }

            user.level.playSound(null,
              user.getX(),
              user.getY(),
              user.getZ(),
              SoundEvents.PLAYER_ATTACK_SWEEP,
              user.getSoundSource(),
              1.0F,
              1.0F);

            double d0 = (double) (-Mth.sin(user.getYRot() * ((float) Math.PI / 180)));
            double d1 = (double) Mth.cos(user.getYRot() * ((float) Math.PI / 180));
            if (user.level instanceof ServerLevel)
            {
                ((ServerLevel) user.level).sendParticles(ParticleTypes.SWEEP_ATTACK,
                  user.getX() + d0,
                  user.getY(0.5D),
                  user.getZ() + d1,
                  2,
                  d0,
                  0.0D,
                  d1,
                  0.0D);
            }

            lastAoeUseTime = user.level.getGameTime();
        }
    }

public void startHelpCitizen(final LivingEntity attacker)
    {
        if (canHelp(attacker.blockPosition()))
        {
            ((IThreatTableEntity) worker).getThreatTable().addThreat(attacker, 20);
            registerTarget(new AIOneTimeEventTarget(CombatAIStates.ATTACKING));
        }
    }

public boolean canHelp(final BlockPos pos)
    {
        if ((getState() == CombatAIStates.NO_TARGET || getState() == GUARD_SLEEP) && canBeInterrupted())
        {
            if (buildingGuards.getTask().equals(GuardTaskSetting.GUARD) && !isWithinPersecutionDistance(pos, getPersecutionDistance()))
            {
                return false;
            }

            // Stop sleeping when someone called for help
            stopSleeping();
            return true;
        }
        return false;
    }

public boolean isWithinPersecutionDistance(final BlockPos entityPos, final double attackRange)
    {
        return BlockPosUtil.getDistanceSquared(getTaskReferencePoint(), entityPos) <= Math.pow(getPersecutionDistance() + attackRange, 2);
    }

@Override
    public boolean canBeInterrupted()
    {
        if (fighttimer > 0 || getState() == CombatAIStates.ATTACKING || worker.getLastAttacker() != null || buildingGuards.getRallyLocation() != null || buildingGuards.getTask()
                                                                                                                                                           .equals(GuardTaskSetting.FOLLOW))
        {
            return false;
        }
        return super.canBeInterrupted();
    }

public static boolean isAttackableTarget(final AbstractEntityCitizen user, final LivingEntity entity)
    {
        if (IColonyManager.getInstance().getCompatibilityManager().getAllMonsters().contains(ForgeRegistries.ENTITY_TYPES.getKey(entity.getType())) && !user.getCitizenData()
                                                                                                                                                          .getWorkBuilding()
                                                                                                                                                          .getModuleMatching(
                                                                                                                                                            EntityListModule.class,
                                                                                                                                                            m -> m.getId()
                                                                                                                                                                   .equals(
                                                                                                                                                                     HOSTILE_LIST))
                                                                                                                                                          .isEntityInList(
                                                                                                                                                            ForgeRegistries.ENTITY_TYPES.getKey(
                                                                                                                                                              entity.getType())))
        {
            return true;
        }

        final IColony colony = user.getCitizenColonyHandler().getColonyOrRegister();
        if (colony == null)
        {
            return false;
        }

        // Players
        if (entity instanceof Player && (colony.getPermissions().getRank((Player) entity).isHostile() || colony.isValidAttackingPlayer((Player) entity)))
        {
            return true;
        }

        // Other colonies guard citizen attacking the colony
        if (entity instanceof EntityCitizen otherCitizen && otherCitizen.getCitizenColonyHandler().getColonyId() != colony.getID()
            && colony.isValidAttackingGuard((AbstractEntityCitizen) entity))
        {
            return true;
        }

        return false;
    }

public void addThreat(final LivingEntity attacker, final int additionalThreat)
    {
        if (attacker instanceof FakePlayer)
        {
            return;
        }
        ThreatTableEntry threatTableEntry = null;
        int index = threatList.size();

        for (int i = 0; i < index; i++)
        {
            final ThreatTableEntry entry = threatList.get(i);
            if (entry.getEntity() == attacker)
            {
                threatTableEntry = entry;
                index = i;
                break;
            }
        }

        if (threatTableEntry == null)
        {
            threatTableEntry = new ThreatTableEntry(attacker);
            threatList.add(threatTableEntry);
            threatTableEntry.addThreat(Math.max(0, MAX_DIST_THREAT - (owner.blockPosition().distManhattan(attacker.blockPosition()) / 4)));
            threatTableEntry.addThreat((int) Math.max(0, MAX_HEALTH_THREAT - (3 * (attacker.getHealth() / attacker.getMaxHealth()))));
        }

        threatTableEntry.addThreat(additionalThreat);
        adaptTableToThreat(index);
    }

public ThreatTableEntry getTarget()
    {
        if (threatList.isEmpty())
        {
            return null;
        }

        // Threat value target change thresholds
        ThreatTableEntry current = threatList.get(currentTargetIndex);
        final ThreatTableEntry top = threatList.get(0);
        if (top.getThreat() > current.getThreat())
        {
            if (top.getEntity().distanceToSqr(owner) > MELEE_RANGE)
            {
                // Targets not in meleerange need 30% more threat than current to cause a target change
                if (top.getThreat() > (current.getThreat() * 1.3))
                {
                    currentTargetIndex = 0;
                    current = top;
                }
            }
            else
            {
                // Targets in meleerange need 10% more threat than current to cause a target change
                if (top.getThreat() > (current.getThreat() * 1.1))
                {
                    currentTargetIndex = 0;
                    current = top;
                }
            }
        }

        if (Math.abs(owner.level().getGameTime() - current.getLastSeen()) > MAX_TRACKING_TICKS || !current.getEntity().canBeSeenAsEnemy())
        {
            removeCurrentTarget();
            return getTarget();
        }

        if (current.getThreat() < 0)
        {
            return null;
        }

        if (current instanceof IThreatTableEntity threatTableEntity && threatTableEntity.getThreatTable().threatList.isEmpty())
        {
            threatTableEntity.getThreatTable().addThreat(owner, 0);
        }

        return current;
    }

public void markInvalidTarget()
    {
        if (threatList.isEmpty())
        {
            return;
        }

        final ThreatTableEntry entry = threatList.get(currentTargetIndex);
        if (!entry.getEntity().isAlive())
        {
            removeCurrentTarget();
            return;
        }

        if (entry.getThreat() != -1)
        {
            entry.setThreat(-1);
            threatList.remove(currentTargetIndex);
            currentTargetIndex = 0;
            threatList.add(entry);
        }
    }

protected void addThreat(final int threat)
    {
        if (threat == 0)
        {
            return;
        }

        this.threat = Math.max(0, this.threat + threat);
        lastSeen = entity.level().getGameTime();
    }
